import { useEffect } from 'react'
import { useAsync } from 'react-async'
import { useParams } from 'react-router-dom'
import { useDebouncedValue } from 'react-use'
import { useGetInventory } from '@/api/inventory'
import { useGetPets } from '@/api/pets'
import { useGetShelters } from '@/api/shelters'
import { useGetSpecies } from '@/api/species'

export function InventoryPage() {
  const { id } = useParams()
  const { data: pets, error: petError, isLoading: petLoading } = useGetPets(id)
  const { data: shelters, error: shelterError, isLoading: shelterLoading } = useGetShelters()
  const { data: species, error: speciesError, isLoading: speciesLoading } = useGetSpecies()

  const { data: inventory, error: inventoryError, isLoading: inventoryLoading } = useGetInventory(
    {
      filter: { shelterId: id },
      sort: 'name',
    },
    { enabled: shelterLoading }
  )
  const inventoryFiltered = inventory || []

  const [search, setSearch] = useDebouncedValue('')

  const { data: speciesFiltered } = useGetSpecies(
    {
      filter: { name: search },
      sort: 'name',
    },
    { enabled: speciesLoading }
  )

  const [filter, setFilter] = useAsync({ initialValue: { shelterId: id } })
  const { data: filterFiltered } = useGetInventory(
    {
      filter,
      sort: 'name',
    },
    { enabled: filterLoading }
  )

  const { data: inventoryFiltered } = useGetInventory(
    {
      filter: { shelterId: filterFiltered.data.shelterId },
      sort: 'name',
    },
    { enabled: filterLoading }
  )

  useEffect(() => {
    if (petError || petLoading || shelterError || shelterLoading || speciesError || speciesLoading || inventoryError || inventoryLoading) {
      setSearch('')
    }
  }, [petError, petLoading, shelterError, shelterLoading, speciesError, speciesLoading, inventoryError, inventoryLoading])

  return (
    <>
      <div className="flex h-screen flex-col items-center justify-center">
        <div className="text-center py-12 text-4xl font-bold leading-10 sm:text-5xl sm:leading-14">
          Inventory page
        </div>
        <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
          {inventoryFiltered.map(({ shelterId, name, description, species }) => (
            <div key={name}>
              <h1 className="text-2xl font-semibold">{name}</h1>
              <p className="text-sm leading-relaxed">{description}</p>
              <h3 className="text-2xl font-semibold">{species}</h3>
            </div>
          ))}
        </div>
        <div className="mt-8 text-center">
          <p className="text-sm leading-relaxed">
            This is a demo page. You can try the API with{' '}
            <a
              className="font-semibold underline"
              href="https://petstore.swagger.io/"
              target="_blank"
              rel="noreferrer"
            >
              swagger.io
            </a>
            .
